$exe = 'C:\Program Files\ImageDataViewer\ImageDataViewer.App.exe' if (-not (Test-Path -LiteralPath $exe)) { throw "未找到：$exe" }
$desktop = [Environment]::GetFolderPath('CommonDesktopDirectory') $lnk = Join-Path $desktop 'ImageDataViewer.lnk' $shell = New-Object -ComObject WScript.Shell $shortcut = $shell.CreateShortcut($lnk) $shortcut.TargetPath = $exe $shortcut.WorkingDirectory = 'C:\Program Files\ImageDataViewer' $shortcut.Description = '图像数据查看器' $shortcut.Save() if (-not (Test-Path -LiteralPath $lnk)) { throw "桌面快捷方式创建失败：$lnk" }
Write-Output "ImageDataViewer 快捷方式：$lnk"

$exe = 'C:\Program Files\ImageDataViewer\ImageDataViewer.App.exe'
if (-not (Test-Path -LiteralPath $exe)) {
    throw "未找到：$exe"
}
$running = Get-Process -Name 'ImageDataViewer.App' -ErrorAction SilentlyContinue
if (-not $running) {
    Start-Sleep -Seconds 2
    $running = Get-Process -Name 'ImageDataViewer.App' -ErrorAction SilentlyContinue
}
if ($running) {
    Write-Output '关闭安装后自动启动的 ImageDataViewer，准备导入规则。'
    $running | Stop-Process -Force
    Start-Sleep -Seconds 2
}
$package = Join-Path $env:IPCDEPLOYMENT_FILES_DIR '下料规则.idvpack'
if (-not (Test-Path -LiteralPath $package)) {
    throw "未找到规则包：$package"
}
$rule = '下料规则'
$arguments = '--import-package "' + $package + '" --rule "' + $rule + '"'
$process = Start-Process -FilePath $exe -ArgumentList $arguments -Wait -PassThru
if ($process.ExitCode -eq 7) {
    Write-Output 'ImageDataViewer 仍在运行，关闭后重试。'
    Get-Process -Name 'ImageDataViewer.App' -ErrorAction SilentlyContinue | Stop-Process -Force
    Start-Sleep -Seconds 2
    $process = Start-Process -FilePath $exe -ArgumentList $arguments -Wait -PassThru
}
switch ($process.ExitCode) {
    0 { Write-Output '规则导入并激活成功。' }
    2 { throw '规则导入失败：参数错误或规则名不存在（退出码 2）。' }
    3 { throw '规则导入失败：规则包读取失败（退出码 3）。' }
    4 { throw '规则导入失败：包内没有可导入的规则（退出码 4）。' }
    5 { Write-Output '警告：规则已导入，但激活失败（根目录不可用，退出码 5）；请在软件中手工修复。' }
    6 { throw '规则导入失败：写入失败（退出码 6）。' }
    7 { throw '规则导入失败：ImageDataViewer 正在运行（退出码 7）。' }
    default { throw "规则导入失败，退出码 $process.ExitCode。" }
}
$log = Join-Path $env:ProgramData ('ImageDataViewer\Logs\' + (Get-Date -Format 'yyyy-MM-dd') + '.log')
Write-Output ("日志：$log")

$target = 'C:\Program Files\JinovisionLogAnalyzer' $zip = Join-Path $env:IPCDEPLOYMENT_DATA_ROOT 'software\JinovisionLogAnalyzer-1.4.1-win-x64.zip' if (-not (Test-Path -LiteralPath $zip)) { throw "未找到日志分析工具安装包：$zip" } if (Test-Path -LiteralPath $target) { Write-Output "清理旧目录：$target" Remove-Item -LiteralPath $target -Recurse -Force } New-Item -ItemType Directory -Force -Path $target | Out-Null Write-Output "解压日志分析工具到：$target" Expand-Archive -LiteralPath $zip -DestinationPath $target -Force
$exe = Join-Path $target 'JinovisionLogAnalyzer.Wpf.exe' if (-not (Test-Path -LiteralPath $exe)) { throw "解压后未找到：$exe" }
$desktop = [Environment]::GetFolderPath('CommonDesktopDirectory') $lnk = Join-Path $desktop 'Jinovision 日志分析工具.lnk' $shell = New-Object -ComObject WScript.Shell $shortcut = $shell.CreateShortcut($lnk) $shortcut.TargetPath = $exe $shortcut.WorkingDirectory = $target $shortcut.Description = 'Jinovision 日志分析工具' $shortcut.Save() if (-not (Test-Path -LiteralPath $lnk)) { throw "桌面快捷方式创建失败：$lnk" }
Write-Output "日志分析工具安装完成：$exe" Write-Output "桌面快捷方式：$lnk"

$target = 'C:\Program Files\ApowerREC'
